INSERT INTO "drill" VALUES(1,1,'跨部门要资源，对方说排期满了','你是市场部的项目负责人，下周要上线一个促销活动，需要技术部的张工帮忙开发一个活动页面。你去找张工时，他皱着眉说：“这个月排期已经满了，你们市场部每次都临时加需求。”请你说明需求的价值与紧迫性，理解对方的难处，并提出可行的协作方案（如缩小范围、调整优先级、请对方领导协调），争取对方支持。','','中压',3,'纯语音','技术部开发工程师张工，工作很忙，对市场部临时加需求有怨气，但讲道理','市场部项目负责人','换位思考、需求价值表达、提出双赢的协作方案','又是你们市场部啊？这个月排期早就满了，你们每次都临时加需求，我真排不过来。','','online',0);
INSERT INTO "drill" VALUES(2,2,'年度绩效面谈，争取加薪','你在公司工作满两年，今年独立负责了两个重点项目，业绩超额完成 30%。年度绩效面谈时，你的直属领导刘经理说：“今年整体预算紧张，调薪幅度都不大。”请你用事实和数据说明自己的贡献，合理表达加薪诉求，同时给领导留有余地，必要时提出替代方案（如职级晋升、培训机会、下半年复议）。','','中压',4,'纯语音','直属领导刘经理，认可下属但受预算约束，会委婉推脱','工作两年、业绩突出的员工','用数据说话、坚定而不强硬、灵活提出替代方案','来，坐。今年你表现确实不错，不过我得先跟你说一下，今年整体预算比较紧张，调薪幅度普遍都不大。你自己怎么看？','','online',0);
INSERT INTO "drill" VALUES(3,3,'下属连续延期交付，一对一沟通','你是一个 6 人小组的组长。组员小王最近连续两次延期交付，影响了整个项目进度，但他平时能力不错。你约他做一次一对一沟通。请你先了解原因，再明确指出问题和影响，最后和他一起制定改进计划，既要解决问题，也要保护他的积极性。','','低压',3,'纯语音','组员小王，能力不错但最近状态下滑，一开始有点防御','6 人小组的组长','倾听询问、就事论事给反馈、共同制定改进计划','组长，你找我？……是不是因为上周那个需求又延期了的事？','','online',0);
INSERT INTO "drill" VALUES(4,4,'会议跑题争吵，你来拉回主线','你主持一场产品需求评审会，议题是确定下个版本的三个核心功能。会议进行到一半，运营的小陈和设计的老周因为一个按钮颜色争执起来，已经偏题十分钟。请你礼貌地打断，肯定双方的观点，把讨论拉回主议题，并给出明确的后续处理方式和时间安排。','','中压',3,'纯语音','运营小陈，情绪有点激动，坚持自己的观点，会试图继续争论','产品需求评审会的主持人','适时打断、中立肯定、拉回议程、明确行动项','不是，老周你听我说完！这个按钮必须用红色，用户根本注意不到灰色的，数据我都看过……','','online',0);
INSERT INTO "drill" VALUES(5,5,'电梯偶遇大老板，30 秒闲聊','早上你在电梯里偶遇公司的赵总，电梯里只有你们两个人，大约有 30 秒到一分钟的时间。赵总主动问你：“最近在忙什么呀？”请你自然得体地回应，简要介绍自己的工作亮点，并找到一个轻松的话题延续交流，给老板留下积极的印象。','','低压',2,'纯语音','公司赵总，亲和但时间宝贵，会随口追问一两句','普通员工','简洁表达工作亮点、自然寒暄、把握分寸','早啊！你是……产品部的吧？最近在忙什么呀？','','online',0);
INSERT INTO "drill" VALUES(6,6,'年终客户答谢宴，你来致祝酒词','公司年终客户答谢宴，十几位重要客户和公司领导都在场。领导临时让你作为项目负责人，给大家敬第一杯酒并说几句。请你用 1 分钟左右的祝酒词，感谢客户一年来的支持，回顾合作成果，表达对来年的期待，营造热络得体的氛围。','','中压',3,'纯语音','公司领导王总，在桌上点名让你说话，之后会以客户身份接话回应','项目负责人','结构清晰的祝酒词：感谢—回顾—祝福，语气真诚热情','来来来，大家静一静！今天咱们项目负责人也在，这一年辛苦了，你代表咱们团队先给各位贵宾敬一杯，说两句！','','online',0);
INSERT INTO "drill" VALUES(7,7,'饭局冷场，你来破冰','你参加一个朋友组织的饭局，桌上有一半人互相不认识，开席十分钟大家都在低头看手机，气氛有点冷。坐在你旁边的是第一次见面的李先生。请你找合适的话题开启聊天，并逐步把更多人带进话题，让气氛热起来。','','低压',3,'纯语音','饭局上第一次见面的李先生，有点拘谨，起初回答简短，被带动后会逐渐放开','饭局参与者','寻找共同话题、开放式提问、把话题抛给更多人','（放下手机）嗯？你好你好……你也是小周的朋友？','','online',0);
INSERT INTO "drill" VALUES(8,8,'同事说错话，客户脸色一沉','你和同事小张陪客户吃饭。小张喝多了，随口说了一句：“你们公司上次那个付款拖了三个月，我们财务都快疯了。”客户孙总脸色一沉，桌上瞬间安静。请你迅速圆场，化解尴尬，既维护客户面子，又不让同事下不来台，把气氛重新带回来。','','高压',3,'纯语音','客户孙总，被冒犯后有些不悦，语气冷淡，会试探你们公司的态度','陪同客户吃饭的业务负责人','快速反应、幽默或真诚化解尴尬、照顾各方面子','（放下筷子）哦？拖了三个月？那看来我们合作得挺让你们为难的啊。','','online',0);
INSERT INTO "drill" VALUES(9,9,'饭桌上请老前辈引荐资源','你在创业，正在找一家大型连锁超市的采购渠道。今晚的饭局上，你终于和行业老前辈陈总坐在了一起，他和这家超市的采购总监关系很好。请你在合适的时机自然地提出请求，说清楚你的项目价值，让陈总愿意帮你引荐，同时不让对方感到被利用。','','中压',4,'纯语音','行业老前辈陈总，阅历丰富、爱惜羽毛，不会轻易答应帮忙，会考察你','创业者','铺垫关系、把握时机、清晰表达价值、给对方台阶','小伙子，听说你最近在创业？做的什么项目啊，说来听听。','','online',0);
INSERT INTO "drill" VALUES(10,10,'重要饭局迟到 40 分钟','今晚是部门为新领导接风的饭局，你因为临时处理客户问题迟到了 40 分钟。你推门进去时，大家已经吃了一半，有同事起哄：“迟到的要先自罚三杯！”新领导吴总也看着你。请你得体地道歉、说明原因（不找借口）、应对罚酒，并顺势向新领导表示欢迎。','','中压',2,'纯语音','起哄的同事老刘，爱热闹，会坚持让你罚酒；新领导吴总偶尔插话','迟到的部门员工','真诚道歉、得体应对劝酒、顺势表达欢迎','哎哟，大忙人终于来了！迟到四十分钟啊，按规矩先自罚三杯！吴总可都等你半天了。','','online',0);
INSERT INTO "drill" VALUES(11,11,'面试自我介绍有方法，助你迅速赢得考官青睐','你正在参加一家互联网公司的产品经理岗位面试，面试官是部门负责人郑总。面试开始，郑总说：“先用两分钟做个自我介绍吧。”请你结合目标岗位，用“我是谁—我做过什么—我为什么适合”的结构，突出与岗位相关的经历和成果，并准备好应对面试官的追问。','','低压',4,'纯语音','面试官郑总，专业友善，会针对你提到的经历追问一两个细节','应聘产品经理的求职者','结构化自我介绍、突出岗位匹配度、用成果说话','你好，欢迎来面试。我们开始吧，先用两分钟做个自我介绍。','','online',0);
INSERT INTO "drill" VALUES(12,12,'行业沙龙上结识分享嘉宾','你参加了一场行业沙龙，刚才的分享嘉宾林老师讲得非常精彩。茶歇时你走到林老师身边，想认识他并建立联系。请你用具体、真诚的赞美开启对话（避免空洞的“讲得真好”），自然地介绍自己，并争取到加微信或后续交流的机会。','','低压',3,'纯语音','分享嘉宾林老师，客气但被很多人围着，对泛泛的夸奖反应平淡，对具体的问题感兴趣','行业沙龙参会者','具体真诚的赞美、自然自我介绍、提出连接请求','（端着咖啡转过身）你好，有什么事吗？','','online',0);
INSERT INTO "drill" VALUES(13,13,'向不太熟的邻居借车位','你的父母下周来住一周，需要一个停车位。你注意到楼上邻居周阿姨的车位一直空着，但你们只是点头之交。今天在楼下碰到她，请你礼貌地开口请求借用车位一周，说明情况，主动提出回报方式，并在对方犹豫时得体应对。','','低压',3,'纯语音','邻居周阿姨，和善但有些谨慎，会担心车位被长期占用','小区住户','礼貌开口、说清需求与期限、主动给对方保障和回报','哎，小伙子，下班啦？','','online',0);
INSERT INTO "drill" VALUES(14,14,'聚会上被当众调侃收入','同学聚会上，一位多年不见的老同学当着大家的面说：“听说你还在那个小公司啊？一个月能挣多少，够在这儿买个厕所吗？”大家都笑了，看向你。请你保持风度，既不卑不亢地回应冒犯，又不把气氛搞僵，必要时巧妙地把话题转移开。','','高压',2,'纯语音','爱炫耀、说话不过脑子的老同学大刘，会继续调侃一两句','参加同学聚会的你','情绪稳定、幽默或坚定地设立边界、转移话题','哈哈，听说你还在那个小公司啊？一个月能挣多少，够在咱这儿买个厕所吗？','','online',0);
INSERT INTO "drill" VALUES(15,15,'给妈妈打电话，说出一直没说的感谢','今天是妈妈的生日，你在外地工作没能回家。你一直想对她说些感谢的话，但平时总是不好意思开口。请你在这通电话里，用具体的回忆和细节表达对妈妈的感谢和爱，而不只是“生日快乐”。妈妈可能会害羞地岔开话题，请你温和地把话说完。','','低压',3,'纯语音','妈妈，接到电话很开心，被表达感谢时会不好意思、习惯性地关心你吃饭和工作','在外地工作的子女','用具体细节表达情感、坦然说出爱与感谢','喂？哎呀，这么晚还打电话，吃饭了没有？','','online',0);
INSERT INTO "drill" VALUES(16,16,'客户来电投诉产品质量','你是一家家电品牌的客服主管。客户黄先生买的空调安装不到一周就不制冷，售后两次上门都没修好，他打电话来非常愤怒，要求退货并赔偿，否则就去网上曝光。请你先安抚情绪、表达共情，再了解诉求，在公司政策范围内给出解决方案。','','高压',4,'纯语音','愤怒的客户黄先生，语气激烈、会打断你、威胁投诉曝光，被真诚对待后会逐渐缓和','家电品牌客服主管','先处理情绪再处理事情、共情倾听、给出具体解决方案','你们到底还管不管了？！空调买了不到一周就不制冷，修了两次都没修好，大热天的我家孩子都中暑了！今天必须给我退货赔钱，不然我就去网上曝光你们！','','online',0);
INSERT INTO "drill" VALUES(17,17,'小剐蹭，对方情绪激动','下班高峰，你开车并线时和旁边车道的车发生了轻微剐蹭，双方车辆都只是掉了点漆。对方车主下车后很激动，认为全是你的责任，要求你赔 2000 元私了。你认为双方都有责任。请你保持冷静，先确认安全，再理性沟通，提出合理的处理方式（如报警、走保险或协商金额）。','','高压',3,'纯语音','对方车主，着急赶时间、情绪激动，坚持是你全责','发生剐蹭的车主','情绪稳定、讲事实不指责、提出合理的解决路径','你怎么开车的？！并线不看后视镜啊？你看把我车蹭成什么样了！你全责，赔两千私了，我还赶时间呢！','','online',0);
INSERT INTO "drill" VALUES(18,18,'被同事误会抢功劳','上周的季度汇报上，你介绍了项目成果，但同事小郑认为你把他负责的部分说成是你自己做的，现在他对你很冷淡，还在别人面前抱怨。你其实在汇报时提到了团队，只是没有点他的名字。请你主动找他沟通，澄清误会，承认疏忽，修复关系。','','中压',3,'纯语音','同事小郑，心里有委屈，一开始冷淡、带刺，被真诚对待后会软化','做季度汇报的同事','主动沟通、先认可对方感受、澄清事实、承认不足','（头也不抬）有事吗？我挺忙的。','','online',0);
INSERT INTO "drill" VALUES(19,19,'供应商要求涨价 15%','你是公司的采购经理。合作三年的包装材料供应商何总找你，说原材料涨价，要求从下个月起涨价 15%，否则只能减少供货。你的预算最多能接受 5% 的涨幅。请你了解对方的真实困难，挖掘双方的利益点（如签长期合同、增加订量、调整付款周期），谈出一个双方都能接受的方案。','','中压',4,'纯语音','供应商何总，确实面临成本压力，立场坚定但愿意谈条件','公司采购经理','探询对方真实需求、交换条件、创造双赢方案','王经理，咱们合作三年了，我就直说吧。今年原材料涨得太厉害，下个月开始我们得涨价 15%，不然真的做不下去了。','','online',0);
INSERT INTO "drill" VALUES(20,20,'临时点名发言不慌乱，展现临场应变与表达力','你是公司销售部的一名员工，正在参加季度项目复盘会，会议主题是“如何提升下一季度的客户转化率”。领导讲到改进方案时突然点名：“小李，你接触客户比较多，说说你的看法。”毫无准备的你，请使用“即兴发言2步走”“即兴演讲4大公式”快速整理思路，在1分钟内说出自己的观点和建议。','','低压',3,'纯语音','销售部领导王总，主持复盘会，友善但会追问建议的可执行性','销售部员工小李','即兴发言结构（先表态再展开，如“观点—原因—案例—总结”）、1 分钟内清晰表达','小李，你接触客户比较多，说说你的看法？下个季度咱们的转化率怎么提上去？','','online',0);
INSERT INTO "drill" VALUES(21,21,'项目受挫后，给团队打气','你带领的团队花了三个月准备的投标项目刚刚失败了，大家都很沮丧，有人开始怀疑方向。周一早会上，你需要对团队讲几句话。请你承认失败、肯定大家的付出、总结可以带走的收获，并明确下一步目标，让团队重新振作起来。','','中压',3,'纯语音','团队里的老员工阿峰，情绪低落、有些消极，会提出质疑','团队负责人','共情承认失败、肯定付出、给出希望与清晰的下一步','（叹气）老大，说实话，三个月白干了……大家现在都挺没劲的，你说咱们这方向到底还对不对？','','online',0);
